INSERT INTO verses_yousafzai (id, ref, book, chapter, verse, text, text_normalized, testament, translation_key, dialect, audio_r2_key, audio_public_url, created_at, updated_at, tags) VALUES
(18701, 'Jeremiah 34:13', 'Jeremiah', 34, 13, '&nbsp;”ما ستاسو د پلار نيکۀ سره لوظ وکړو کله چې ما هغوئ د مِصر نه د غلامۍ د مُلک نه رابهر او آزاد کړل. نو ما وفرمائيل چې،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(18702, 'Jeremiah 34:14', 'Jeremiah', 34, 14, '&nbsp;په هر يو اوؤم کال تاسو هر هغه عبرانى چې خپل ځان يې په تاسو خرڅ کړے دے آزاد کړئ. د شپږ کاله د خِدمت کولو نه وروستو، نو په کار دے چې تاسو هغه آزاد کړئ او رُخصت يې کړئ. خو ستاسو پلار نيکۀ زما خبرو ته نۀ غوږ ونيولو او نۀ يې ورته توجو ورکړه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(18703, 'Jeremiah 34:15', 'Jeremiah', 34, 15, '&nbsp;خو اوس تاسو پښېمانه شوئ او توبه مو وويستله او خپله فېصله مو بدله کړه او هغه کار مو وکړو چې څۀ زما په نظر کښې صحيح وو، او تاسو هر يو د خپلو غلامانو د آزادولو اعلان وکړو. او دا چې تاسو زما په کور کښې چې زما د نوم مهر پرې لګولے شوے دے ما سره لوظ وکړو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(18704, 'Jeremiah 34:16', 'Jeremiah', 34, 16, '&nbsp;خو تاسو بيا خپله فېصله بدله کړه او زما د نوم بې‌حرمتى مو وکړه، او تاسو بيا هر يو سړے غلام او ښځه مو واپس وينځه کړه څوک چې تاسو آزاد کړى وُو. نو بيا تاسو هغوئ په زور سره دوباره غلامان او وينځې کړل.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(18705, 'Jeremiah 34:17', 'Jeremiah', 34, 17, '&nbsp;نو ځکه مالِک خُدائ فرمائى چې، تاسو زما پيروى ونۀ کړه، تاسو د خپل مُلک خلقو ته د آزادۍ اعلان ونۀ کړو. نو زۀ اوس بيا تاسو ته دغه شان د آزادۍ اعلان کوم. مالِک خُدائ فرمائى چې ستاسو آزادى به داسې وى چې زۀ به تاسو په تُورې، وبا او قحط باندې مړۀ کړم. زۀ به تاسو ټولې دُنيا ته د عبرت او د يرې سبب وګرځوم.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(18706, 'Jeremiah 34:18', 'Jeremiah', 34, 18, '&nbsp;ځکه چې تاسو ما سره د لوظ شرائط مات کړل نو زۀ به تاسو هم دوه ځايه کړم لکه څنګه چې تاسو سخى دوه ځايه کړى وُو او د هغې په مينځ کښې تېر شوئ.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(18707, 'Jeremiah 34:19', 'Jeremiah', 34, 19, '&nbsp;آو، زۀ به تاسو په مينځ وشلوم، هغه کۀ تاسو د يهوداه او يروشلم آفسران، د دربار خصيان آفسران، اِمامان او يا عام خلق هم يئ، ځکه چې تاسو ما سره خپل لوظ مات کړو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(18708, 'Jeremiah 34:20', 'Jeremiah', 34, 20, '&nbsp;نو زۀ به مو خپلو دشمنانو ته حواله کړم څوک چې ستاسو مرګ پسې ګرځى. ستاسو د مړو لاشونه به د هوا د مارغانو او د ګيدړانو خوراک کړم.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(18709, 'Jeremiah 34:21', 'Jeremiah', 34, 21, '&nbsp;زۀ به د يهوداه بادشاه صدقياه او د هغۀ آفسران هم د هغوئ دشمنانو ته حواله کړم څوک چې د هغوئ مرګ پسې ګرځى. کۀ څۀ هم چې د بابليانو د بادشاه لښکرو خپلې حملې ستاسو خلاف بندى کړى دى،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(18710, 'Jeremiah 34:22', 'Jeremiah', 34, 22, '&nbsp;مالِک خُدائ فرمائى چې، زۀ به هغوئ ته حُکم ورکړم او بيا به زۀ هغوئ واپس دې ښار ته راولم. هغوئ به ستاسو خلاف جنګ وکړى او هغوئ به دا ښار قبضه کړى او وبه يې سوزوى. او زۀ به د يهوداه ښارونه وران او تباه کړم نو بيا به څوک هم هلته نۀ اوسيږى.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(18711, 'Jeremiah 35:1', 'Jeremiah', 35, 1, '&nbsp;د مالِک خُدائ پېغام يرمياه ته د يهويقيم د يوسياه د زوئ د حکومت په دوران کښې ورکړے شو او هغۀ ته يې وفرمائيل چې،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(18712, 'Jeremiah 35:2', 'Jeremiah', 35, 2, '&nbsp;”د ريکاب خاندان ته لاړ شه او هغوئ ته دعوت ورکړه چې د مالِک خُدائ کور ته راشى نو بيا هغوئ هلته يوې کوټې ته بوځه او د څښلو دپاره ورله مے ورکړه.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(18713, 'Jeremiah 35:3', 'Jeremiah', 35, 3, '&nbsp;نو بيا زۀ يازنياه د يرمياه زوئ او د حبصنيا نمسى ته او د هغۀ زامنو او وروڼو او د ريکاب مکمل خاندان ته ورغلم.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(18714, 'Jeremiah 35:4', 'Jeremiah', 35, 4, '&nbsp;ما هغوئ ټول د مالِک خُدائ کور ته او د يجدليا د زوئ حنان پېغمبر او د هغۀ د زامنو کوټې ته راوستل چې د خُدائ پاک خادِم وو. دا کوټه د آفسرانو د کوټې سره خوا کښې او د معسياه د سلوم زوئ چې چوکيدار وو د هغۀ د کوټې دپاسه وه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(18715, 'Jeremiah 35:5', 'Jeremiah', 35, 5, '&nbsp;نو بيا ما جامونه سره د پيالو راواخستل او د ميو نه مې ډک کړل او هغه مې د ريکاب خاندان ته پېش کړل او ورته مې ووئيل چې، ”راشئ او مے وڅښئ.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(18716, 'Jeremiah 35:6', 'Jeremiah', 35, 6, '&nbsp;خو هغوئ راته په جواب کښې ووئيل چې، ”مونږ مے نۀ څښو، ځکه چې زمونږ نيکۀ يوندب د ريکاب زوئ مونږ ته دا حکم راکړے دے چې تاسو او ستاسو اولاد دې کله هم مے نۀ څښى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(18717, 'Jeremiah 35:7', 'Jeremiah', 35, 7, '&nbsp;او تاسو کورونه مۀ جوړَوئ، او تخم مۀ کَرئ، او مۀ د انګورو باغونه کَرئ او تاسو چې هيڅکله دا کارونه ونۀ کړئ، او ضرورى ده چې په خپلو خېمو کښې اوسېږئ. نو بيا به تاسو په هغه زمکه تر ډېره وخته پورې ژوندى پاتې شئ چرته چې تاسو د مسافرو په شان ژوند کوئ.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(18718, 'Jeremiah 35:8', 'Jeremiah', 35, 8, '&nbsp;مونږ د هغه هر څۀ تابع يُو د څۀ چې مونږ ته زمونږ نيکۀ يوندب د ريکاب زوئ تعليم راکړے دے. نۀ خو مونږ او نۀ زمونږ ښځو او نۀ زمونږ زامنو لوڼو کله مے څښلى دى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(18719, 'Jeremiah 35:9', 'Jeremiah', 35, 9, '&nbsp;او نۀ مونږ د اوسېدو دپاره کورونه جوړ کړى او نۀ مو د انګور باغ، پټى يا فصلونه کَرلى دى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(18720, 'Jeremiah 35:10', 'Jeremiah', 35, 10, '&nbsp;مونږ په خېمو کښې اوسېدلو او په هر هغه څۀ مو پوره عمل کړے دے څۀ چې مونږ ته زمونږ نيکۀ يوندب حکم کړے وو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(18721, 'Jeremiah 35:11', 'Jeremiah', 35, 11, '&nbsp;خو کله چې نبوکدنضر بادشاه په دې مُلک باندې قبضه وکړه، مونږ ووئيل، راځئ چې، مونږ يروشلم ته د بابليانو او د شام د لښکرو نه وتښتُو. نو بيا ځکه مونږ په يروشلم کښې پاتې شُو.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(18722, 'Jeremiah 35:12', 'Jeremiah', 35, 12, '&nbsp;نو بيا د مالِک خُدائ کلام په يرمياه نازل شو، او وې فرمائيل چې،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(18723, 'Jeremiah 35:13', 'Jeremiah', 35, 13, '&nbsp;”دا هغه کلام دے چې مالِک خُدائ ربُ الافواج د بنى اِسرائيلو خُدائ پاک فرمائى چې، لاړ شه او د يهوداه سړو او د يروشلم خلقو ته ووايه چې، آيا تاسو د دې نه سبق نۀ زده کوئ او زما د کلام پيروى نۀ کوئ؟', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(18724, 'Jeremiah 35:14', 'Jeremiah', 35, 14, '&nbsp;يوندب د ريکاب زوئ خپلو بچو ته حکم وکړو چې مے مۀ څښئ نو هغوئ د هغۀ دا حکم ومنلو. تر نن ورځ پورې چا هم په هغوئ کښې مے ونۀ څښل، ځکه چې هغوئ د خپل پلار نيکۀ د حکم پيروى کوى. خو ما تاسو سره په څو څو ځله خبرې وکړې خو تاسو زما د خبرو پيروى ونۀ کړه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(18725, 'Jeremiah 35:15', 'Jeremiah', 35, 15, '&nbsp;ما تاسو ته بار بار خپل نبيان درولېږل. هغوئ تاسو ته وفرمائيل چې، په تاسو کښې دې هر يو د خپلو بدو کارونو نه واوړى او ښۀ کارونه دې کوى، او مۀ تاسو د نورو معبودانو پيروى کوئ او مۀ يې خِدمت کوئ. نو بيا به تاسو په هغه زمکه کښې اوسېږئ کومه چې ما ستاسو پلار نيکۀ ته ورکړې ده. خو تاسو زما خبرو ته توجو ورنۀ کړه او نۀ مو غوږ ونيولو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(18726, 'Jeremiah 35:16', 'Jeremiah', 35, 16, '&nbsp;يوندب چې د ريکاب زوئ د هغۀ اولاد د خپل پلار حُکم ومنلو او د هغې پيروى يې وکړه، خو تاسو خلقو زما خبره ونۀ منله.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(18727, 'Jeremiah 35:17', 'Jeremiah', 35, 17, '&nbsp;نو د دې په وجه مالِک خُدائ ربُ الافواج د بنى اِسرائيلو خُدائ پاک فرمائى چې، ما ته غوږ شئ‎. زۀ اوس د يهوداه او د يروشلم په ټولو خلقو باندې هغه ټول افتونه راولم د کومو چې ما د هغوئ خلاف اعلان کړے دے. ما هغوئ ته ووئيل، خو هغوئ غوږ ونۀ نيولو. ما هغوئ ته آواز وکړو، خو هغوئ ما ته جواب رانۀ کړو.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(18728, 'Jeremiah 35:18', 'Jeremiah', 35, 18, '&nbsp;نو يرمياه د ريکاب خاندان ته وفرمائيل، ”مالِک خُدائ، ربُ الافواج د بنى اِسرائيلو خُدائ پاک فرمائى چې، تاسو خو د خپل پلار نيکۀ يوندب حکم ومنلو او د هغۀ د ټولو هداياتو مو تابعدارى وکړه او په هر هغه څۀ باندې مو عمل وکړو چې هغۀ درته وئيلى وُو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(18729, 'Jeremiah 35:19', 'Jeremiah', 35, 19, '&nbsp;نو په دې وجه مالِک خُدائ ربُ الافواج د بنى اِسرائيلو خُدائ پاک فرمائى چې، د يوندب د ريکاب د زوئ په خاندان کښې به همېشه يو سړے داسې وى چې زما خِدمت به کوى.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(18730, 'Jeremiah 36:1', 'Jeremiah', 36, 1, '&nbsp;په يهوداه کښې د يهويقيم د يوسياه د زوئ د بادشاهۍ په څلورم کال، مالِک خُدائ يرمياه ته پېغام ورکړو چې،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(18731, 'Jeremiah 36:2', 'Jeremiah', 36, 2, '&nbsp;”يو طومار راواخله او په هغې زما ټول کلام کوم چې ما درته د يهوداه، د اِسرائيل او د ټولو قومونو په خلاف د يوسياه د بادشاهۍ د وخت نه تر اوسه پورې نازل کړے دے وليکه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(18732, 'Jeremiah 36:3', 'Jeremiah', 36, 3, '&nbsp;شايد چې د يهوداه خلق د هغه ټولو افتونو په حقله واورى کوم چې زما په هغوئ د راوستلو نيت دے، نو کۀ هر يو د خپلې بدعملۍ نه راوګرځى نو بيا به زۀ د هغوئ ګناهونه او بدعملونه معاف کړم.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(18733, 'Jeremiah 36:4', 'Jeremiah', 36, 4, '&nbsp;نو بيا يرمياه باروک د نيرياه زوئ راوغوښتلو، او کله چې يرمياه هغۀ ته هغه هر څۀ ووئيل کوم چې مالِک خُدائ هغۀ ته فرمائيلى وُو، نو باروک هغه په يو طومار کښې وليکل.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(18734, 'Jeremiah 36:5', 'Jeremiah', 36, 5, '&nbsp;نو بيا يرمياه باروک ته وفرمائيل چې، ”زۀ دلته نظر بند يم نو د مالِک خُدائ کور ته دننه تلے نۀ شم.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(18735, 'Jeremiah 36:6', 'Jeremiah', 36, 6, '&nbsp;نو بيا تاسو د مالِک خُدائ کور ته کله چې روژه وى لاړ شئ او خلقو ته هغه څۀ ولولئ کوم چې ما تاسو ته وفرمائيل او تاسو هغه په يو طومار کښې وليکل. دا د يهوداه ټولو هغه خلقو ته ولوله کوم چې د خپلو ښارونو نه د عبادت دپاره دلته راغلى وى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(18736, 'Jeremiah 36:7', 'Jeremiah', 36, 7, '&nbsp;شايد چې هغوئ مالِک خُدائ ته عرض او مِنت زارى وکړى او ټول د خپلو بدو لارو نه راوګرځى، ځکه چې د مالِک خُدائ قهر او غضب ډېر لوئ دے کوم چې يې د دې خلقو خلاف اعلان کړے دے.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(18737, 'Jeremiah 36:8', 'Jeremiah', 36, 8, '&nbsp;باروک د نيرياه زوئ هم هغه شان وکړل څنګه چې ورته يرمياه نبى حکم کړے وو، نو د هغه طومار نه يې د مالِک خُدائ کلام د مالِک خُدائ په کور کښې ولوستلو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(18738, 'Jeremiah 36:9', 'Jeremiah', 36, 9, '&nbsp;يهويقيم د يوسياه زوئ د يهوداه بادشاه د بادشاهۍ د پينځم کال په نهمه مياشت د يروشلم ټولو خلقو ته او د هغوئ دپاره څوک چې د يهوداه د ښارونو نه راغلى وُو، د روژې اعلان وکړو او هغوئ د مالِک خُدائ دپاره روژه ونيوله.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(18739, 'Jeremiah 36:10', 'Jeremiah', 36, 10, '&nbsp;د مالِک خُدائ په کور کښې د ګمرياه د سافن زوئ منشى د کوټې نه، کومه چې د دربار په بره حِصه کښې وه او د مالِک خُدائ د کور د داخلېدو د نوې دروازې سره نزدې وه، باروک ټولو خلقو ته چې هلته موجود وُو د يرمياه کلام د طومار نه تلاوت کړو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(18740, 'Jeremiah 36:11', 'Jeremiah', 36, 11, '&nbsp;کله چې ميکاياه د ګمرياه زوئ او د سافن نمسى د مالِک خُدائ کلام د طومار نه واورېدو،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(18741, 'Jeremiah 36:12', 'Jeremiah', 36, 12, '&nbsp;نو هغه په شاهى محل کښې لاندې د منشى کوټې ته لاړو، چرته چې ټول آفسران ناست وُو. اليسمع، د دربار منشى، د سمعياه زوئ دلاياه، د عکبور زوئ الناتن، د سافن زوئ ګمرياه، د حننياه زوئ صدقياه او نور ټول آفسران هلته موجود وُو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(18742, 'Jeremiah 36:13', 'Jeremiah', 36, 13, '&nbsp;نو ميکاياه هغوئ ته هغه هر څۀ ووئيل څۀ چې باروک خلقو ته د طومار نه بيانول او هغۀ ترې اورېدلى وُو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(18743, 'Jeremiah 36:14', 'Jeremiah', 36, 14, '&nbsp;نو ټولو آفسرانو په مشورې سره يهودى د نتنياه زوئ، د شلمياه نمسى او د کوشى کړوسے باروک ته ورولېږلو چې ورته دا ووائى، ”آفسران وائى چې راشه، او ځان سره هغه طومار هم راوړه کوم چې تا ټولو خلقو ته ولوستلو.“ نو باروک د نيرياه زوئ د هغه طومار سره چې کوم يې په لاس کښې وو هغوئ له ورغلو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(18744, 'Jeremiah 36:15', 'Jeremiah', 36, 15, '&nbsp;نو هغوئ هغۀ ته ووئيل چې، ”مهربانى وکړه دلته کښېنه او مونږ ته دا طومار ولوله.“ نو باروک ورته هغه طومار ولوستلو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(18745, 'Jeremiah 36:16', 'Jeremiah', 36, 16, '&nbsp;نو کله چې هغوئ دا کلام واورېدو، نو بيا هغوئ يو بل ته يرې سره کتل او باروک ته يې ووئيل چې، ”مونږ به ضرور بادشاه د دې ټول کلام نه خبر کړُو.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(18746, 'Jeremiah 36:17', 'Jeremiah', 36, 17, '&nbsp;نو بيا هغوئ د باروک نه تپوس وکړو چې، ”تۀ مونږ ته دا ووايه چې دا هر څۀ تا څنګه وليکل؟ آيا يرمياه نبى تا ته وفرمائيل او تا وليکل؟“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(18747, 'Jeremiah 36:18', 'Jeremiah', 36, 18, '&nbsp;باروک ورته جواب ورکړو چې، ”آو، هغۀ دا هر څۀ ما ته وفرمائيل او ما هغه په دې طومار کښې په سياهۍ باندې وليکل.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(18748, 'Jeremiah 36:19', 'Jeremiah', 36, 19, '&nbsp;نو آفسرانو باروک ته ووئيل چې، ”تۀ او يرمياه لاړ شئ او خپل ځان پټ کړئ. او هيچا ته مۀ وايئ چې تاسو چرته يئ.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(18749, 'Jeremiah 36:20', 'Jeremiah', 36, 20, '&nbsp;نو بيا آفسرانو هغه طومار د دربار د منشى اليسمع په کوټه کښې کېښودو، نو بيا هغوئ د بادشاه دربار ته لاړل او د دې ټول کلام نه يې بادشاه خبر کړو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(18750, 'Jeremiah 36:21', 'Jeremiah', 36, 21, '&nbsp;نو بادشاه يهودى نومې سړے ورولېږلو چې هغه طومار راوړى، نو يهودى هغه د اليسمع منشى د کوټې نه راوړو او بادشاه او هغه ټولو آفسرانو ته چې ورسره په خوا کښې ولاړ وُو ولوستلو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(18751, 'Jeremiah 36:22', 'Jeremiah', 36, 22, '&nbsp;نو د کال نهمه مياشت وه، د يخنۍ موسم وو نو بادشاه په شاهى محل کښې د ژمى دپاره په جوړه شوې کوټه کښې نغرى ته ناست وو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(18752, 'Jeremiah 36:23', 'Jeremiah', 36, 23, '&nbsp;هرکله چې يهودى درې څلور عنوانونه ولوستل، نو بادشاه دا طومار په چاقو وشلولو او هغه يې په نغرى کښې اور ته واچولو، تر دې چې هغه طومار ټول په اور کښې وسوزېدو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(18753, 'Jeremiah 36:24', 'Jeremiah', 36, 24, '&nbsp;بادشاه او د هغۀ ټولو خِدمتګارانو چا چې دا کلام واورېدو هغوئ ونۀ يرېدل او نۀ يې د غم نه جامې وشلولې.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(18754, 'Jeremiah 36:25', 'Jeremiah', 36, 25, '&nbsp;کۀ څۀ هم چې الناتن، دلاياه او ګمرياه بادشاه ته مِنتُونه کول چې طومار مۀ سوزوه خو هغۀ د هغوئ خبرې ته غوږ ونۀ نيولو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(18755, 'Jeremiah 36:26', 'Jeremiah', 36, 26, '&nbsp;نو بيا د دې په ځائ بادشاه يرحمئيل شهزاده او ورسره سراياه د عزرائيل زوئ او شلمياه د عبدائيل زوئ ته حکم وکړو چې باروک منشى او يرمياه نبى ګرفتار کړى. خو مالِک خُدائ هغوئ پټ کړل.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(18756, 'Jeremiah 36:27', 'Jeremiah', 36, 27, '&nbsp;کله چې يهويقيم هغه طومار وسوزولو چې په کښې هغه الفاظ وُو کوم چې باروک ته يرمياه فرمائيلى وُو او هغۀ ليکلى وُو، نو د مالِک خُدائ کلام په يرمياه نازل شو او ورته يې وفرمائيل چې،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(18757, 'Jeremiah 36:28', 'Jeremiah', 36, 28, '&nbsp;”يو بل طومار راواخله او په هغې کښې هغه هر څۀ وليکه څۀ چې په اول طومار کښې ليکلے شوى وُو کوم چې يهويقيم د يهوداه بادشاه وسوزولو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(18758, 'Jeremiah 36:29', 'Jeremiah', 36, 29, '&nbsp;نو همدارنګه يهويقيم د يهوداه بادشاه ته ووايه، مالِک خُدائ داسې فرمائى چې، تا دا طومار وسوزولو او يرمياه ته دې وئيل چې، تا ولې په دې کښې دا ليکلى دى چې په يقين سره به د بابل بادشاه راشى او په حقيقت کښې به دا مُلک تباه کړى او انسان او ځناور داوړه به په کښې جارُو کړى؟', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(18759, 'Jeremiah 36:30', 'Jeremiah', 36, 30, '&nbsp;نو په دې وجه مالِک خُدائ د يهويقيم د يهوداه بادشاه په حقله فرمائى چې، د هغۀ په اولاد کښې به څوک هم د داؤد په تخت بادشاهى ونۀ کړى، او د هغۀ لاش به په خوشى مېدان وغورزولے شى چرته چې په ورځ کښې به نمر او په شپه کښې به سختې يخنۍ او پرخې ته پروت وى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(18760, 'Jeremiah 36:31', 'Jeremiah', 36, 31, '&nbsp;زۀ به هغۀ ته او د هغۀ اولاد او د هغۀ نوکرانو ته د هغوئ د غلطو کارونو په وجه سزا ورکړم، زۀ به په دوئ او په هغه چا باندې چې په يروشلم کښې اوسيږى او د يهوداه په ټولو خلقو به هغه افتونه راولم کوم چې ما د هغوئ خلاف اعلان کړى دى، ځکه چې هغوئ ما ته غوږ ونۀ نيولو.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(18761, 'Jeremiah 36:32', 'Jeremiah', 36, 32, '&nbsp;بيا يرمياه يو بل تش طومار راواخستلو او باروک ليکوال د نيرياه زوئ له يې ورکړو، نو څنګه به چې يرمياه فرمائيل نو هغه ټول الفاظ يې په کښې دوباره وليکل کوم چې په هغه طومار کښې ليکلے شوى وُو چې يهويقيم د يهوداه بادشاه په اور کښې اچولے او سوزولے وو. او د هغې نه علاوه يې نوره هم په دې موضوع رڼا واچوله.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(18762, 'Jeremiah 37:1', 'Jeremiah', 37, 1, '&nbsp;د يهوداه بادشاه يهوياکين د يهويقيم زوئ د تخت نه د راکوزولو نه وروستو د بابل بادشاه نبوکدنضر د هغۀ په ځائ صدقياه د يوسياه زوئ د يهوداه بادشاه مقرر کړو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(18763, 'Jeremiah 37:2', 'Jeremiah', 37, 2, '&nbsp;نۀ خو صدقياه او نۀ د هغۀ خِدمتګارانو او نۀ په يهوداه کښې پاتې شوى خلقو د مالِک خُدائ په کلام عمل کولو کوم چې د يرمياه په وسيله اورولے شوے وو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(18764, 'Jeremiah 37:3', 'Jeremiah', 37, 3, '&nbsp;خو بيا هم صدقياه بادشاه يهوکل د شلمياه زوئ او صفنياه اِمام د معسياه زوئ يوه ورځ دواړه يرمياه نبى ته ورولېږل او د هغۀ ته يې خواست وکړو چې، ”مونږ ته زمونږ د مالِک خُدائ نه دُعا وغواړه.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(18765, 'Jeremiah 37:4', 'Jeremiah', 37, 4, '&nbsp;تر اوسه يرمياه په قېدخانه کښې نۀ وو اچولے شوے او هر چرته چې يې زړۀ غوښتل هلته په خلقو کښې آزاد ګرځېدلو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(18766, 'Jeremiah 37:5', 'Jeremiah', 37, 5, '&nbsp;په هم هغه وخت کښې د فِرعون فوجيانو مِصر پرېښودو او د يهوداه خوا ته روان شول، نو کله چې د بابليانو فوجيانو چا چې يروشلم محاصره کړے وو د هغوئ د راتلو په حقله واورېدل نو هغوئ د يروشلم نه وروستو شول.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(18767, 'Jeremiah 37:6', 'Jeremiah', 37, 6, '&nbsp;نو بيا په هغه وخت کښې مالِک خُدائ يرمياه نبى ته پېغام ورکړو', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(18768, 'Jeremiah 37:7', 'Jeremiah', 37, 7, '&nbsp;او وې فرمائيل چې، ”صدقياه د يهوداه بادشاه چا چې تۀ رالېږلے يې چې زما نه تپوس وکړى هغۀ ته ووايه، د مِصر فوجيان کوم چې په دې تکل راروان وُو چې ستاسو مدد وکړى هغوئ به زر خپل مُلک مِصر ته واپس لاړ شى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(18769, 'Jeremiah 37:8', 'Jeremiah', 37, 8, '&nbsp;نو بابليان به واپس راوګرځى او په دې ښار باندې به حمله وکړى، هغوئ به دا ښار قبضه کړى او اور به ورته واچوى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(18770, 'Jeremiah 37:9', 'Jeremiah', 37, 9, '&nbsp;مالِک خُدائ داسې فرمائى چې، خپل ځان ته دا دوکه مۀ ورکوئ چې ګنې د بابليانو فوج ستاسو نه لاړو او بيا به نۀ راځى، ځکه چې هغوئ به بيا واپس راځى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(18771, 'Jeremiah 37:10', 'Jeremiah', 37, 10, '&nbsp;تر دې چې کۀ تاسو د بابليانو ټولو لښکرو ته په جنګ کښې شکست هم ورکړئ او د هغوئ په خېمو کښې صرف هغه زخميان سړى وُو چې د جنګ نه ژوندى پاتې شوى وُو، نو هغوئ به راپاڅى او دا ښار به ټول وسوزوى.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(18772, 'Jeremiah 37:11', 'Jeremiah', 37, 11, '&nbsp;کله چې د بابليانو فوجيان د مِصريانو د فوجيانو د رارسېدو په وجه د يروشلم د محاصرې نه راواپس او په شا شُو،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(18773, 'Jeremiah 37:12', 'Jeremiah', 37, 12, '&nbsp;نو يرمياه د دې دپاره د يروشلم د ښار نه د بنيامين قبائيلى علاقې ته په سفر روان شو ترڅو چې هلته کښې د خپلو خپلوانو نه زمکه کښې خپله برخه جائيداد جدا کړى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(18774, 'Jeremiah 37:13', 'Jeremiah', 37, 13, '&nbsp;خو کله چې هغه د بنيامين دروازې ته ورسېدو، نو هلته د چوکيدارانو آفسر د اِرياه په نوم چې د شلمياه زوئ او د حننياه نمسے وو هغه ونيولو. او ورته يې ووئيل، ”تۀ بګوړه شوے يې او د بابليانو سره ملګرے کېږې.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(18775, 'Jeremiah 37:14', 'Jeremiah', 37, 14, '&nbsp;خو يرمياه ورته وفرمائيل چې، ”دا رښتيا نۀ دى. زۀ بګوړه نۀ يم او بابليانو سره نه ملګرے کېږم.“ خو اِرياه هغۀ ته غوږ ونۀ نيولو، او يرمياه يې ونيولو او آفسرانو ته يې پېش کړو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(18776, 'Jeremiah 37:15', 'Jeremiah', 37, 15, '&nbsp;هغوئ يرمياه ته سخت غصه شول او وې وهلو او د يونتن منشى په کور کښې يې بند کړو، د کوم نه چې هغوئ جيل جوړ کړے وو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(18777, 'Jeremiah 37:16', 'Jeremiah', 37, 16, '&nbsp;يرمياه يې په يوه تاخانه کښې بند کړو او تر ډېره وخته پورې هلته په کښې وو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(18778, 'Jeremiah 37:17', 'Jeremiah', 37, 17, '&nbsp;نو څۀ موده پس صدقياه بادشاه څوک ورولېږلو او يرمياه يې خپل محل ته راوغوښتلو، او هغۀ نه يې په راز کښې تپوس وکړو چې، ”د مالِک خُدائ د طرف نه څۀ پېغام شته څۀ؟“ يرمياه جواب ورکړو چې، ”آو، تۀ به د بابل بادشاه ته په حواله کړے شې.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(18779, 'Jeremiah 37:18', 'Jeremiah', 37, 18, '&nbsp;نو بيا يرمياه د صدقياه بادشاه ته وفرمائيل چې، ”ما ستا يا ستا د آفسرانو او يا د دې خلقو خلاف څۀ داسې بد کړى دى چې د هغې په وجه تاسو زۀ په دې قېد کښې اچولے يم؟', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(18780, 'Jeremiah 37:19', 'Jeremiah', 37, 19, '&nbsp;ستاسو په هغه نبيانو باندې څۀ چل وشو چې تاسو ته به يې وئيل چې، د بابل بادشاه به نۀ په تاسو او نۀ په دې مُلک باندې حمله وکړى؟', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(18781, 'Jeremiah 37:20', 'Jeremiah', 37, 20, '&nbsp;نو اوس، بادشاه سلامته، زۀ تا ته سوال او مِنت کوم چې زما خبره واوره. ما د يونتن منشى کور ته واپس مۀ لېږه، ګنې زۀ به هلته مړ شم.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(18782, 'Jeremiah 37:21', 'Jeremiah', 37, 21, '&nbsp;نو صدقياه بادشاه حُکم وکړو چې يرمياه د يونتن منشى کور ته مۀ استوئ بلکې د هغې په ځائ يې د فوجيانو په چاوڼۍ کښې بند کړئ. او بيا بادشاه دا حکم هم وکړو چې هره ورځ ورته د تنور يوه روټۍ تر هغه وخته پورې ورکوئ ترڅو چې په ټول ښار کښې يوه روټۍ هم وى. نو يرمياه بيا د فوجيانو چاوڼۍ کښې بند کړے شو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(18783, 'Jeremiah 38:1', 'Jeremiah', 38, 1, '&nbsp;سفطياه د متان زوئ، جدلياه د فشحور زوئ، يهوکل د شلمياه زوئ او فشحور د مُلکياه زوئ هغه څۀ واورېدل چې يرمياه ټولو خلقو ته وفرمائيل چې،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(18784, 'Jeremiah 38:2', 'Jeremiah', 38, 2, '&nbsp;”مالِک خُدائ فرمائى چې، هر څوک چې په دې ښار کښې ايسار شى نو هغوئ به په جنګ، قحط او د وبا په وجه مړۀ شى. خو هر څوک چې خپل ځان بابليانو ته حواله کړى، نو هغوئ به ژوندى پاتې شى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(18785, 'Jeremiah 38:3', 'Jeremiah', 38, 3, '&nbsp;مالِک خُدائ داسې هم فرمائى چې، دا ښار به په يقين سره د بابل د بادشاه فوجيانو ته حواله کړے شى او هغوئ به يې قبضه کړى.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(18786, 'Jeremiah 38:4', 'Jeremiah', 38, 4, '&nbsp;نو بيا آفسران بادشاه له ورغلل او ورته يې ووئيل چې، ”دا سړے دې خامخا قتل کړے شى، ځکه چې هغه په ښار کښې زمونږ خلق او په جنګ کښې بچ شوى فوجيان په خپلو دې خبرو باندې بې‌زړۀ کوى. هغه د خلقو ښېګړه نۀ لټوى بلکې په دې خبرو سره ورته نقصان ورکوى.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(18787, 'Jeremiah 38:5', 'Jeremiah', 38, 5, '&nbsp;صدقياه بادشاه ورته په جواب کښې ووئيل چې، ”صحيح ده، هغه اوس ستاسو په لاس کښې دے. زۀ تاسو نۀ شم منع کولے.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(18788, 'Jeremiah 38:6', 'Jeremiah', 38, 6, '&nbsp;نو بيا هغوئ يرمياه ونيولو او په پړو يې د قېدخانې په دربار کښې ډيګۍ ته ورکوز کړو کوم چې د مُلکياه شهزاده ملکيت وو. نو په هغه ډيګۍ کښې اوبۀ نۀ وې، خو لاندې په بېخ کښې ډيرې بوختې وې او يرمياه په هغې کښې ډوب شو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(18789, 'Jeremiah 38:7', 'Jeremiah', 38, 7, '&nbsp;خو د ايتهوپيا خصى عبيدمَلِک د دربار يو اهم شخصيت د دې نه خبر شو چې هغوئ يرمياه په ډيګۍ کښې اچولے شوے دے. په دغه وخت کښې بادشاه د بنيامين په دروازه کښې ناست وو او عدالت يې شروع کړے وو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(18790, 'Jeremiah 38:8', 'Jeremiah', 38, 8, '&nbsp;نو عبيدمَلِک هلته لاړو او بادشاه ته يې ووئيل چې،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(18791, 'Jeremiah 38:9', 'Jeremiah', 38, 9, '&nbsp;”بادشاه سلامت، دې سړو ډېر زيات بد کار وکړو په دې چې هغوئ يرمياه نبى د اوبو په ډيګۍ کښې واچولو. هغه به ډېر زر د لوږې نه مړ شى، ځکه چې په ښار کښې روټۍ ختمه شوه.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(18792, 'Jeremiah 38:10', 'Jeremiah', 38, 10, '&nbsp;نو بادشاه عبيدمَلِک له حُکم ورکړو چې، ”د دې ځائ نه ځان سره دېرش سړى بوځه او يرمياه د مړ کېدو نه وړاندې د هغه ډيګۍ نه راوباسه.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(18793, 'Jeremiah 38:11', 'Jeremiah', 38, 11, '&nbsp;نو عبيدمَلِک د ځان سره کسان واخستل او په شاهى محل کښې د خزانې نه لاندې کمرې ته لاړو او د خپل ځان سره يې څۀ زړې جامې چِرړې راواخستلې. او هغه يې يرمياه ته د پړى په ذريعه ډيګۍ ته ښکته کړې.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(18794, 'Jeremiah 38:12', 'Jeremiah', 38, 12, '&nbsp;عبيدمَلِک يرمياه ته آواز ورکړو او ورته يې ووئيل چې، ”دا زړې کپړې او جامې په خپلو ترخونو کښې کېږده چې د راختو په وخت کښې دې پړے زخمى نۀ کړى.“ يرمياه هم هغه شان وکړل،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(18795, 'Jeremiah 38:13', 'Jeremiah', 38, 13, '&nbsp;او هغوئ هغه د ډيګۍ نه په پړو راوويستلو. او بيا يرمياه د فوجيانو په چاوڼۍ کښې بندى پاتې شو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(18796, 'Jeremiah 38:14', 'Jeremiah', 38, 14, '&nbsp;يوه ورځ صدقياه بادشاه، يرمياه پسې کسان ورولېږل او هغه يې خپل ځان ته د مالِک خُدائ د کور درېمې دروازې ته راوستو. بادشاه ورته ووئيل چې، ”زۀ غواړم چې تا نه يو څو تپوسونه وکړم. نو د هيڅ قسمه حقيقت او رښتيا پټولو کوشش مۀ کوه.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(18797, 'Jeremiah 38:15', 'Jeremiah', 38, 15, '&nbsp;يرمياه ورته وفرمائيل، ”کۀ چرې زۀ تاسو ته رښتيا ووايم، نو تاسو به ما مړ کړئ. او کۀ چرې زۀ تاسو ته نصيحت وکړم، نو تاسو به ما ته غوږ ونۀ نيسئ.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(18798, 'Jeremiah 38:16', 'Jeremiah', 38, 16, '&nbsp;نو بيا صدقياه بادشاه د هغۀ سره په پټه وعده وکړه او ورته يې ووئيل چې، ”زۀ په مالِک خُدائ درته قسم خورم څوک چې ژوندے دے، او څوک چې مونږ ته ژوند راکوى، نۀ به زۀ تا مړ کړم او نۀ به دې هغه کسانو ته حواله کړم څوک چې تا وژل غواړى.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(18799, 'Jeremiah 38:17', 'Jeremiah', 38, 17, '&nbsp;نو په هغه وخت کښې بيا يرمياه صدقياه د يهوداه بادشاه ته وفرمائيل چې، ”مالِک خُدائ ربُ الافواج د بنى اِسرائيلو خُدائ پاک داسې فرمائى چې، کۀ چرې تاسو خپل ځان د بابل آفسرانو ته حواله کړئ، تاسو او ستاسو خاندان به ژوندى پاتې شئ، او دا ښار به د سوزېدو نه بچ شى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(18800, 'Jeremiah 38:18', 'Jeremiah', 38, 18, '&nbsp;خو کۀ تاسو د خپل ځان د حواله کېدو نه اِنکار وکړئ، نو دا ښار به بابليانو ته حواله کړے شى، او هغوئ به دا ښار د سر نه تر آخره پورې وسوزوى. او تاسو به ترې نۀ شئ تښتېدلے.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]');